insert:
INSERT INTO tc_model_secs_message (
    model_version_key, secs_msg_name, description, data_index, created_at, updated_at
) VALUES (
    #{m.modelVersionKey}, #{m.secsMsgName}, #{m.description}, #{m.dataIndex}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
)

select:
SELECT 
  FROM tc_model_secs_message
 WHERE model_version_key = #{modelVersionKey}
   AND secs_msg_name = #{secsMsgName}

SELECT 
  FROM tc_model_secs_message
 WHERE model_version_key = #{modelVersionKey}
 ORDER BY secs_msg_key ASC

    LIMIT #{limit} OFFSET #{offset}
